'messages.Switch the status on to display this section to users; turn it off to remove it from the landing page.','messages.Location Picker Section','messages.To instantly match customers with your service availability, creating immediate relevance and preventing failed order attempts.','messages.What is Tax ?','messages.Let’s Setup',
'messages.Common types include','messages.VAT (Value Added Tax)','messages.GST (Goods & Services Tax)','messages.Service Tax','messages.Sales Tax',
'messages.Why Set Up Taxes ?','messages.Enabling tax in your system helps you:','messages.Stay legally compliant with local tax laws','messages.Automatically calculate and apply the correct tax during checkout','messages.Show clear and accurate pricing to customers',
'messages.Generate ready-to-use VAT/GST reports','messages.Once you set up your tax correctly, the system will automatically handle calculations for every order.','messages.Activate the Tax Status','messages.Turn ON the Status toggle to make the tax active.','messages.If it’s OFF, the tax will be saved but not applied to any transaction.',
'messages.Enter a Tax Name','messages.Go to the Tax Name field and enter your preferred name.','messages.Example: Service Tax, VAT, GST, Sales Tax, etc.','messages.Set the Tax Rate','messages.In the Tax Rate box, enter the percentage (e.g., 10%).',
'messages.This is the rate that will be applied to all taxable items or services.','messages.Save the Tax','messages.Click Submit to add the new tax.','messages.Click Reset if you need to clear the form before saving.','messages.You can create multiple taxes for different purposes — for example, separate ones for product, service, and delivery.',
'messages.Follow these steps to add a new tax rate:','messages.Edit or Manage Existing Taxes','messages.Once a tax is created, you cannot change its name or delete it (for data integrity).','messages.However, you can update the tax rate anytime if your government updates the tax percentage.','messages.Manage all your created taxes easily from the Tax List page.',
'messages.Use the Export button to download a copy for backup or accounting records.','messages.Toggle the Status on or off to quickly enable or disable a tax.','messages.You can decide:','messages.Whether tax should be included in the product price or added separately','messages.Which parts of the order should have taxes applied — items, delivery fees, or packaging',
'messages.This gives you full control over how your business handles tax visibility and accuracy.','messages.Tax Calculation Method','messages.You can choose one of two ways to calculate tax:','messages.Calculate Tax Included in Product Price','messages.The tax is already included in the listed item price.',
'messages.The customer sees a single total price (no separate tax line).','messages.Invoices and reports won’t show separate VAT amounts.','messages.Use this method if your displayed prices are “tax-included.','messages.Calculate Tax Excluded from Product Price','messages.The tax is added on top of the item price.',
'messages.Customers will see a separate tax line during checkout and in their invoice.','messages.This method gives you clear, transparent VAT reporting.','messages.Recommendation: Use “Tax Excluded from Product Price” if you want to show taxes separately for better reporting.','messages.Tax Effect on Orders','messages.Before activation:',
'messages.Orders placed earlier will not have any tax added.','messages.After activation:','messages.All new orders will automatically calculate and apply the correct tax.','messages.After deactivation:','messages.If you turn off tax again, future orders will not include tax until reactivated.',
'messages.This ensures older orders stay accurate while new ones follow updated rules.','messages.Flexible Tax Application Options','messages.Order-wise Tax:','messages.One flat tax rate applies to the total order.','messages.Product-wise Tax: ',
'messages.Each product or food item can have its own tax rate.','messages.Category-wise Tax: ','messages.Different product categories can carry different tax rates.','messages.This flexibility lets you match complex tax rules for restaurants, grocery stores, or other service types.','messages.Uploaded Prescription Orders (Pharmacy Module Only)',
'messages.For pharmacy modules, tax applies order-wise on uploaded prescription orders.','messages.You can set the tax type and rate specifically for these orders.','messages.You can also configure tax for packaging charges.','messages.If enabled, packaging costs will include tax as per your setup — ensuring your total billing remains compliant.','messages.Example: If packaging costs $2 and tax is 10%, the total will show as $2.20.',
'messages.Final Step – Save Your Setup','messages.After completing all configurations:','messages.Click Save Information to apply changes.','messages.Click Reset if you want to start over or discard unsaved edits.','messages.Once saved, your tax setup will instantly affect all applicable orders moving forward.',
